/**
 * AI crop advisory — talks to the Kalika backend (`POST /advisory`).
 *
 * The model key lives on the server. `mode` tells the UI whether the answer
 * came from a model ("ai") or from the server's rule-based fallback ("demo").
 * A demo answer is real guidance; it is just not generated by an LLM, and the
 * UI must say so.
 */
import { ApiError, apiFetch } from "@/lib/api";

export type AdvisoryMode = "ai" | "demo";

export type AdvisoryAnswer = {
  mode: AdvisoryMode;
  model: string | null;
  /** Rule topic that matched in demo mode. */
  topic?: string;
  answer: string;
  /** Answer split into steps/paragraphs for rendering. */
  steps: string[];
  /** Shown verbatim when the server had to fall back. */
  notice: string | null;
};

export type AdvisoryRequest = {
  question: string;
  crop?: string | null;
  district?: string | null;
  state?: string | null;
  weather?: string | null;
  language?: string;
};

export type AdvisoryStatus = { configured: boolean; model: string | null };

export async function askAdvisory(body: AdvisoryRequest): Promise<AdvisoryAnswer> {
  return apiFetch<AdvisoryAnswer>("/advisory", {
    method: "POST",
    body: JSON.stringify(body),
  });
}

export async function getAdvisoryStatus(): Promise<AdvisoryStatus> {
  return apiFetch<AdvisoryStatus>("/advisory/status");
}

export async function getAdvisoryTopics(): Promise<string[]> {
  const res = await apiFetch<{ topics: string[] }>("/advisory/topics");
  return res.topics;
}

/** Friendlier copy for the errors this endpoint actually produces. */
export function advisoryErrorMessage(err: unknown): string {
  if (err instanceof ApiError) {
    if (err.status === 422) return err.message || "Please rephrase your question.";
    if (err.status === 503) return "Crop advisory is not available on this server right now.";
    return err.message;
  }
  if (err instanceof TypeError) {
    return "Could not reach the Kalika API. Is the backend running on :8000?";
  }
  return err instanceof Error ? err.message : "Could not get an answer right now.";
}
